inputs = ['kib', 'wdh', 'dacv', 'wkvvju', 'ahbw']
outputs = ['kib', 'wdc', 'dacefz', 'wkefzefzju', 'acbw']

print("Input strings:")
for i, inp in enumerate(inputs):
    print(f"  {i}: '{inp}'")

print("\nOutput strings:")
for i, outp in enumerate(outputs):
    print(f"  {i}: '{outp}'")

print("\nDifferences:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"  {i}: '{inp}' -> '{outp}'")

